// List cells that differ between two structures: node cellDiff.mjs <before.nbt> <after.nbt>
import { load } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
const [a, b] = process.argv.slice(2).map((f) => load(f));
const name = (c) => (c ? String(c.block).replace("minecraft:", "") : "air");
const seen = new Set();
for (const c of a) seen.add(c.pos.join(","));
for (const c of b) seen.add(c.pos.join(","));
const out = [];
for (const k of seen) {
  const [x, y, z] = k.split(",").map(Number);
  const before = name(a.get(x, y, z));
  const after = name(b.get(x, y, z));
  if (before !== after && (before === "spruce_slab" || after === "air" || before === "air")) out.push(`${k} ${before} -> ${after}`);
}
console.log(out.sort().join("\n") || "(no differences)");

